"""Record independent primary spot-checks of the other lane; never mutates its files."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];HERE=Path(__file__).resolve().parent;PEER=HERE.parent/'debates'
read=lambda p:json.loads(p.read_text());G=read(ROOT/'historiography-1920-2000.json');N={n['id'] for n in G['nodes']};p=read(PEER/'proposals.json')['proposals'];s=read(PEER/'sources.json')
checks={
'rea_debates_certeau_bourdieu':('Printed pp55 and59 visually read, with surrounding pp49/53 also checked.','The criticism contrasts tactical descriptions with reproduction/habitus, while retaining admiration. French original1980 and Rendall’s English1984 are distinct; no whole-book or Bourdieu-original reading is claimed.'),
'rea_debates_brubaker_cooper_hall':('Primary printed pp8–9 read from the article PDF (file pages9–10).','The named Hall passage and refusal of indispensability are explicit. Both Rogers Brubaker and Frederick Cooper author the criticism; one joint argument is being projected.'),
'rea_debates_brubaker_cooper_racial_formation':('Primary printed p40 n28 read from the PDF (file page41).','The criticism specifically addresses the1994 Omi/Winant formulation while acknowledging its constructivism. It does not speak for every racial-formation historian or independently verify the cited immigrant-history studies.'),
'rea_debates_arendt_marx':('Primary printed pp79,86,103–104 read; second-edition imprint independently checked.','The labor/work and necessity/freedom criticisms are present. The1958 argument is not dated1998; Margaret Canovan’s1998 introduction is separately credited. Arendt’s opening disavowal of indiscriminate anti-Marxism is retained.'),
'rea_debates_butler_foucault':('Primary printed pp119–120 and124–126 read;1990/1999/2002 imprint independently checked.','The immanent criticism of the Barbin introduction and romanticization is explicit. The locators belong to the1999 edition, not a collated1990 copy; productive use of Foucault remains part of the argument.'),
'rea_debates_ginzburg_foucault':('Primary printed xviii–xx visually checked in the scan.','Ginzburg’s criticism targets exclusion over excluded subjects and refusal of interpretation. John and Anne Tedeschi share the English translation credit. Existing259/268 concern later evidentiary/textual debates rather than this named preface response.'),
'rea_debates_agamben_foucault':('Reformatted primary digital pp12–13 read, with title/English translation imprint checked.','The corrective is explicit, and p13 refuses leveling historical differences between democracy and totalitarianism. Digital page numbers are not Stanford print locators. Existing1568 is the opposite-direction methodological-resource claim, so this is not a duplicate directed critique.'),
'rea_debates_adorno_benjamin':('Primary letter heading/date and printed pp120–123 visually read from the rotated scanned spreads.','The letter identifies18March1936 and argues that both autonomous and reproduced art have contradictory capacities. The English collection is later; no sole translator is inferred and no following1938 letter is treated as the same document.'),
'rea_debates_spivak_deleuze':('University-hosted primary teaching excerpt pp24 and27 read, alongside the current985 source scope.','The Foucault–Deleuze conversation is specifically named and Deleuze’s transparency/representation position is criticized. Retain985’s separate Foucault target; excerpt pagination is not the original1988 article’s pagination.'),
'rea_debates_anderson_pratt':('Primary reformatted digital pp4–5 body discussion of Anderson independently read; Profession91 citation checked in the header.','Pratt analytically appropriates imagined communities in her speech-community/contact-zone discussion. This is not a claim that Anderson thought actual nations homogeneous and not a Pratt-to-Anderson attack.'),
'rea_debates_dubois_gilroy':('Primary preface p.x visually checked independently, after extracted-text inspection.','Double consciousness is explicitly an organizing resource. The scanned manifestation is Verso; the source’s Harvard1993 bibliographic record is not claimed to be that imprint page. Existing241 already describes this debt at field level, so the new personal route is visibility, not discovery of an absent argument.')}
rows=[]
for item in p:
 pid=item['proposal_id'];extent,assessment=checks[pid]
 pair=[dict(id=e['id'],source=e['source'],target=e['target'],kind=e.get('relationship_kind'),claim=e['relationship']) for e in G['edges'] if {e['source'],e['target']}=={item['source'],item['target']}]
 duplicate=[e for e in G['edges'] if e['source']==item['source'] and e['target']==item['target'] and e.get('relationship_kind')==item['relationship_kind']]
 assert item['source'] in N and item['target'] in N and not duplicate
 rows.append(dict(proposal_id=pid,verdict='pass_with_stated_scope',independent_primary_read_extent=extent,assessment=assessment,existing_pair_records=pair,duplicate_directed_kind_records=[e['id'] for e in duplicate],semantic_overlap_notes=['edge_241 already records the Du Bois/Gilroy resource at field level; parent should preserve or explicitly reroute its context.'] if pid.endswith('dubois_gilroy') else [],required_corrections=[]))
local_names={'certeau_practice_primary':'certeau.pdf','rt186_brubaker_identity':'brubaker.pdf','spivak_speak':'spivak.pdf','rt184_pratt_contact':'pratt.pdf','gilroy':'gilroy.pdf','rea_debates_arendt_human_condition':'arendt.pdf','rea_debates_butler_gender_trouble':'butler.pdf','rea_debates_ginzburg_cheese_preface':'ginzburg.pdf','rea_debates_agamben_homo_intro':'agamben_text.pdf','rea_debates_adorno_benjamin_letter':'adorno.pdf'}
witnesses=[]
for source in s['new_sources']+s['source_addenda']:
 sid=source.get('id',source.get('source_id'));path=Path('/tmp/astra-response-debates')/local_names[sid];actual=hashlib.sha256(path.read_bytes()).hexdigest();assert actual==source['witness_sha256'],sid
 witnesses.append(dict(source_id=sid,witness_sha256=actual,matches_peer=True,spotcheck_mode='Independent reading of the primary PDF/text or rendered page images; peer narrative not accepted as proof.'))
report=dict(schema='response_edge_cross_review/1',checked_on='2026-10-25',reviewer='reading_bridge_integration',reviewed_lane='debates',baseline_revision='1.191',status='pass',proposal_count=len(rows),blocking_corrections=0,proposal_file_sha256=hashlib.sha256((PEER/'proposals.json').read_bytes()).hexdigest(),source_file_sha256=hashlib.sha256((PEER/'sources.json').read_bytes()).hexdigest(),primary_witnesses=witnesses,rows=rows,notes=['All11 latest proposals were checked, not just the original10.','No original whole book, translated original or underlying archival example is newly claimed read.','Parent retains merge/deduplication and implementation responsibility; this review changes no peer source or canonical file.'])
(HERE/'cross-review.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
additional=[]
for pid,target,claim,evidence,pages in [
 ('rea_canadian_cross_ginzburg_derrida','derrida','Ginzburg criticizes Derrida’s objections to Foucault’s historical standpoint as a nihilistic obstacle to inquiry into excluded people.','This is Ginzburg’s attributed reading of Derrida. His suggestion that Derrida helped produce Foucault’s change of method is expressly tentative and is not made into a separate influence arrow. Derrida’s and Foucault’s originals were not newly read.','Preface to the Italian edition, English translation p.xviii'),
 ('rea_canadian_cross_ginzburg_furet','francois_furet','Ginzburg disputes Furet’s restriction of subordinate-class history to quantitative and anonymous reconstruction, defending individual cases where the evidence permits.','He explicitly names Furet before defending the possibility of reconstructing individual personalities. This is a methodological criticism, not rejection of quantitative history as such or proof of every Menocchio interpretation. Furet’s underlying text was not newly read.','Preface to the Italian edition, English translation p.xx')]:
 pair=[e['id'] for e in G['edges'] if {e['source'],e['target']}=={'carlo_ginzburg',target}];assert not pair
 additional.append(dict(proposal_id=pid,disposition='include_pending_parent_independent_primary_check',source='carlo_ginzburg',target=target,type='critique',relationship_kind='critique',directed=True,relationship=claim,evidence_note=evidence,source_ids=['rea_debates_ginzburg_cheese_preface'],primary_locator=pages,argument_date='1976 Italian preface;1980 English translation',read_extent='Fresh visual primary scan reading of pp.xviii–xx; neither the full book nor the quoted opponent’s original was read for this check.',credits='Translated by John and Anne Tedeschi; scanned manifestation is the1992 Hopkins paperback of the1980 English translation.',existing_pair_records=pair,source_policy='Reuse the proposed debates-lane primary source exactly; do not overwrite its record.'))
(HERE/'cross-review-additional-proposals.json').write_text(json.dumps(dict(schema='response_cross_review_additional_proposals/1',baseline_revision='1.191',status='prepared_for_parent_independent_review',proposals=additional),ensure_ascii=False,indent=2)+'\n')
print('Independent cross-review PASS:',len(rows),'proposals;',len(witnesses),'primary byte witnesses matched;',len(additional),'new drafts for parent review')
